css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: A4 portrait;
  margin: 0;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  padding: 0 !important;
}

.cd-yearly-count-sheet * {
  box-sizing: border-box;
}

.cd-yearly-count-sheet {
  box-sizing: border-box;
  position: relative;
  width: 180mm;
  color: #222;
  background: #fff;
  font-family: "TH Sarabun Document", sans-serif;
  font-size: 3.7mm;
  line-height: 1.15;
}

.cd-yearly-count-sheet small {
  display: block;
  font-size: 2.7mm;
  color: #555;
}

.cd-yearly-count-sheet .document-header {
  margin-bottom: 4mm;
  border-bottom: 0.4mm solid #222;
  padding-bottom: 3mm;
}

.cd-yearly-count-sheet h1 {
  margin: 0;
  font-size: 6mm;
  font-weight: 700;
}

.cd-yearly-count-sheet h1 small {
  display: inline;
  margin-left: 2mm;
  font-size: 3.6mm;
  font-weight: 400;
}

.cd-yearly-count-sheet .meta-section {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5mm 6mm;
  margin-top: 3mm;
}

.cd-yearly-count-sheet .meta-item {
  display: flex;
  gap: 2mm;
}

.cd-yearly-count-sheet .meta-item .label {
  flex: 0 0 auto;
  font-weight: 700;
}

.cd-yearly-count-sheet .items-section table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.cd-yearly-count-sheet .items-section thead {
  display: table-header-group;
}

.cd-yearly-count-sheet .items-section tr {
  page-break-inside: avoid;
}

.cd-yearly-count-sheet .items-section td {
  padding: 1.3mm 1.5mm;
  border: 0.25mm solid #999;
  vertical-align: top;
  word-break: break-word;
}

.cd-yearly-count-sheet .items-section th {
  padding: 1.3mm 1.5mm;
  border: 0.25mm solid #999;
  vertical-align: top;
  word-break: break-word;
  background: #eee;
  font-weight: 700;
  text-align: center;
}

.cd-yearly-count-sheet .items-section td.count-cell {
  height: 8mm;
}

.cd-yearly-count-sheet col.no {
  width: 5%;
}

.cd-yearly-count-sheet col.item-code {
  width: 13%;
}

.cd-yearly-count-sheet col.item-name {
  width: 22%;
}

.cd-yearly-count-sheet col.batch {
  width: 11%;
}

.cd-yearly-count-sheet col.serial {
  width: 11%;
}

.cd-yearly-count-sheet col.location {
  width: 11%;
}

.cd-yearly-count-sheet col.expiry {
  width: 9%;
}

.cd-yearly-count-sheet col.count-qty {
  width: 18%;
}

.cd-yearly-count-sheet .remarks-footer {
  margin-top: 4mm;
  border-top: 0.25mm solid #999;
  padding-top: 2mm;
}

.cd-yearly-count-sheet .remarks-label {
  font-weight: 700;
}

.cd-yearly-count-sheet .remarks-text {
  min-height: 8mm;
  margin-top: 1mm;
  border: 0.25mm solid #999;
  padding: 1.5mm;
}
